package paladin

import (
	"github.com/wowsims/forever/sim/core"
	"github.com/wowsims/forever/sim/core/spelldata"
)

// Righteous Fury
// https://www.wowhead.com/forever/spell=25780
//
// Increases the threat generated by your Holy attacks by 90%. Lasts 30 min.
func (paladin *Paladin) registerRighteousFury() {
	rank := spellData.RighteousFury.Highest()
	actionID := core.ActionID{SpellID: rank.ID}

	paladin.RighteousFuryAura = paladin.RegisterAura(core.Aura{
		Label:    "Righteous Fury",
		ActionID: actionID,
		Duration: core.NeverExpires,
	})
	spelldata.ParseEffects(&paladin.Character, paladin.RighteousFuryAura, rank, spelldata.Effects(1))

	config := spelldata.SpellConfig(&paladin.Unit, rank, spelldata.Flags(core.SpellFlagAPL))
	config.ProcMask = core.ProcMaskEmpty
	config.ClassSpellMask = SpellMaskRighteousFury
	config.ApplyEffects = func(sim *core.Simulation, _ *core.Unit, spell *core.Spell) {
		spell.RelatedSelfBuff.Activate(sim)
	}
	config.RelatedSelfBuff = paladin.RighteousFuryAura
	paladin.RegisterSpell(config)
}
